"""Original anemia approach and iron-deficiency questions."""
from qbank_authoring import question,ref,finalize
BS=ref('BSG: Management of Iron Deficiency Anaemia in Adults','https://pmc.ncbi.nlm.nih.gov/articles/PMC8515119/')
AG=ref('AGA: Management of Iron Deficiency Anemia, 2024','https://gastro.org/clinical-guidance/management-of-iron-deficiency-anemia/')
GI=ref('AGA: Gastrointestinal Evaluation of Iron Deficiency Anemia','https://agau.gastro.org/Course/AGA_Clinical_Guidelines_on_Gastrointestinal_Evaluation_of_Iron_Deficiency_Anemia_-_Accompanying_Educational_Presentation/d351c1ce-dc6f-4523-9606-868e04ad4359')
AS=ref('ASH: Diagnosis of Iron Deficiency Guidelines, 2026','https://doi.org/10.1182/bloodadvances.2025015950')
RI=ref('McGraw Hill: Approach to the Patient with Anemia—Reticulocyte Production Index','https://accessmedicine.mhmedical.com/content.aspx?bookid=2715&sectionid=249058425')
AI=ref('NEJM: Anemia of Inflammation','https://www.nejm.org/doi/full/10.1056/NEJMra1804281')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('Which initial combination best organizes the evaluation of an otherwise unexplained anemia?', 'Red-cell indices, reticulocyte response and peripheral smear in the clinical context',[
 ('MCV alone as a complete etiological diagnosis','Several causes share an MCV category and mixed deficiencies can mask it.'),('Serum iron alone as a measure of total stores','Serum iron varies and is low in several mechanisms.'),('Immediate marrow biopsy before reviewing basic tests in every patient','Many causes are identified less invasively first.')],
 'Classify morphology and marrow response before narrowing the cause', '**The reticulocyte response separates underproduction from an appropriate regenerative response.**',['Indices and smear add morphological clues.','History identifies bleeding, diet, drugs, systemic disease and inherited risk.'], '**Use focused next tests rather than an indiscriminate panel.**',['Iron studies, B12, renal assessment or hemolysis tests follow the pattern.','Marrow assessment is reserved for a suitable clinical indication.'],[['MCV / smear','Morphology'],['Reticulocytes','Effective marrow response'],['Clinical context','Etiological probability']],[RI,BS])
q('A patient with severe anemia has a reticulocyte percentage of 3%. Why can this still represent an inadequate marrow response?', 'The percentage must be interpreted against the reduced red-cell mass and prolonged reticulocyte maturation',[
 ('Every reticulocyte percentage above 2 is always adequate','An uncorrected percentage can exaggerate the response in severe anemia.'),('Reticulocytes measure only platelet production','They are young red cells.'),('A high percentage excludes mixed nutritional deficiency in every case','The absolute and corrected response and the broader picture matter.')],
 'The denominator changes during anemia', '**Correct for anemia severity and, when using RPI, maturation time.**',['A percentage is not equivalent to an absolute production rate.','Prematurely released reticulocytes remain identifiable longer.'], '**Judge whether the response matches the degree and timing of anemia.**',['Early acute blood loss may precede a brisk response.','Concurrent marrow or nutrient limitation can blunt regeneration.'],[['Uncorrected percent','Can overstate response'],['Correction','Red-cell mass and maturation'],['Clinical use','Production versus loss/destruction']],[RI],style='clinical_scenario')
q('Reticulocytes are 6%, hematocrit is 24% and the reference hematocrit is 45%. If the assigned maturation factor is 2, what is the reticulocyte production index?', '1.6',[
 ('3.2','This is the corrected percentage before dividing by the maturation factor.'),('6.0','This is the uncorrected percentage.'),('12.0','This incorrectly multiplies rather than correcting for anemia and maturation.')],
 'Use the stated assumptions explicitly', '**RPI = reticulocyte % × patient hematocrit/reference hematocrit ÷ maturation factor.**',['6 × 24/45 = 3.2.','3.2 / 2 = 1.6.'], '**The response is not robust for substantial anemia.**',['An RPI around this level suggests a hypoproliferative component.','Interpret with timing, absolute count and the clinical cause.'],[['Corrected percent','3.2'],['Maturation factor','2'],['RPI','1.6']],[RI])
q('A patient has Hb 8.8 g/dL, MCV 69 fL, ferritin 7 ng/mL and high TIBC. Which diagnosis is most likely?', 'Iron deficiency anemia',[
 ('Pure anemia of inflammation','Ferritin is usually preserved or increased and TIBC often low or normal.'),('Isolated beta-thalassemia trait','It does not explain the depleted ferritin; coexistence is possible.'),('Iron overload','The storage and binding pattern is opposite.')],
 'A clearly low ferritin is strong evidence of depleted stores', '**Microcytosis plus low ferritin and increased binding capacity fits absolute iron deficiency.**',['Early deficiency can be normocytic.','Do not require every classic feature to be present.'], '**Replace iron and investigate the cause.**',['Menstrual, gastrointestinal and other losses or malabsorption require consideration.','A response to iron does not remove the need to explain new deficiency in an at-risk adult.'],[['Ferritin','Low stores'],['TIBC','Often increased'],['MCV','Often low in established deficiency']],[BS,AS],style='clinical_scenario')
q('According to ASH 2026 guidance for most adult diagnostic populations, which ferritin threshold is suggested instead of 15 ng/mL to identify iron deficiency?', '30 ng/mL or lower',[
 ('5 ng/mL or lower as the only accepted threshold','That would miss many deficient patients.'),('300 ng/mL or lower as a universal rule without context','That is not the general adult threshold.'),('Any ferritin value if serum iron is low once','A transient low serum iron does not establish absolute deficiency.')],
 'Name the population and guideline when testing a ferritin cutoff', '**ASH 2026 suggests a threshold of at most 30 ng/mL in the relevant adult populations.**',['This is a conditional recommendation and context still matters.','Inflammation requires additional assessment.'], '**Do not confuse this with a different guideline’s evaluation threshold.**',['AGA uses a 45-ng/mL cutoff in anemic patients within its GI-evaluation framework.','Thresholds answer related but not identical diagnostic questions.'],[['ASH 2026 adult framework','≤30 ng/mL'],['AGA anemia/GI framework','<45 ng/mL'],['Inflammation','Interpret with TSAT and context']],[AS,GI])
q('A patient with rheumatoid inflammation has anemia, low serum iron, low TSAT and ferritin 180 ng/mL. What is the best interpretation?', 'Inflammatory iron restriction is plausible, and ferritin alone cannot resolve whether additional absolute deficiency is present',[
 ('The ferritin proves iron overload','Ferritin is an acute-phase reactant.'),('Low serum iron alone proves absent stores','Iron sequestration can lower circulating iron despite stored iron.'),('The patient cannot have an iron-related erythropoietic problem','Inflammation can restrict iron delivery to erythropoiesis.')],
 'Stored iron and available iron can diverge', '**Hepcidin-mediated sequestration can lower circulating iron availability.**',['Ferritin can rise with inflammation.','Assess TSAT, inflammatory activity and other evidence together.'], '**Investigate mixed causes when the degree of anemia is unexplained.**',['Blood loss and nutrient deficiency can coexist.','Do not prescribe chelation solely for an inflammatory ferritin elevation.'],[['Ferritin','Inflammation-sensitive storage marker'],['TSAT','Circulating availability clue'],['Clinical task','Distinguish pure restriction from mixed deficiency']],[AI,AS],style='clinical_scenario')
q('How does increased hepcidin contribute to anemia of inflammation?', 'It promotes ferroportin internalization and reduces iron export from enterocytes and macrophages',[
 ('It increases ferroportin-mediated iron release in all tissues','Its action is inhibitory to ferroportin-mediated export.'),('It directly converts hemoglobin to bilirubin as its main action','That is not the iron-regulatory mechanism.'),('It increases intestinal iron absorption without limit','Inflammation-associated hepcidin reduces absorption and release.')],
 'Hepcidin controls the route by which iron enters plasma', '**Ferroportin is the key cellular iron exporter.**',['Inflammatory signaling can increase hepatic hepcidin.','Macrophage iron retention limits delivery to developing red cells.'], '**The anemia also has non-iron mechanisms.**',['Reduced erythropoietin response and shorter red-cell survival can contribute.','Treat the underlying inflammatory disease and assess other correctable causes.'],[['Hepcidin','Increased with inflammation'],['Ferroportin','Internalized / degraded'],['Result','Reduced plasma iron availability']],[AI])
q('Which pattern most favors thalassemia trait over isolated iron deficiency in a microcytic adult?', 'Marked microcytosis with a relatively preserved or high red-cell count and nondepleted iron stores',[
 ('Ferritin 5 ng/mL with high TIBC','This strongly supports iron deficiency.'),('A rapid MCV fall after substantial chronic blood loss with depleted stores','This favors iron deficiency.'),('Macro-ovalocytes and hypersegmented neutrophils','This suggests a megaloblastic process.')],
 'Microcytosis is not synonymous with iron deficiency', '**Thalassemia trait can produce a disproportionate reduction in MCV.**',['The RBC count is often relatively maintained.','Discrimination indices are screening clues rather than definitive diagnosis.'], '**Confirm with appropriate hemoglobin and genetic testing.**',['Iron deficiency and a hemoglobinopathy can coexist.','Avoid indefinite iron without evidence of deficiency.'],[['Iron deficiency','Depleted stores and often rising RDW'],['Thalassemia trait','Disproportionate microcytosis / preserved RBC count'],['Confirmation','Appropriate hemoglobin or genetic assessment']],[BS])
q('An older man has newly confirmed iron deficiency anemia but no GI symptoms. Which investigation principle is appropriate?', 'Evaluate for a gastrointestinal source, commonly with bidirectional endoscopy after appropriate assessment',[
 ('No GI assessment is needed without abdominal pain','GI pathology can be clinically silent.'),('A negative symptom history proves dietary deficiency','It does not exclude occult blood loss.'),('Iron response alone eliminates concern for a GI lesion','A bleeding lesion can coexist with a good hematologic response.')],
 'Unexplained iron deficiency can be the presentation of occult GI disease', '**Men and postmenopausal women generally warrant upper and lower GI evaluation.**',['Assess fitness and tailor tests to symptoms or contraindications.','Screen for relevant malabsorptive causes such as celiac disease.'], '**Treat deficiency while investigating the mechanism.**',['Do not delay necessary iron replacement without a reason.','Document and follow completion of the diagnostic pathway.'],[['Patient','At-risk adult with new IDA'],['Investigation','Upper and lower GI assessment'],['Parallel care','Iron replacement and follow-up']],[GI,BS],style='clinical_scenario')
q('Which additional diagnosis should be considered in otherwise unexplained or refractory iron deficiency, even without prominent diarrhea?', 'Celiac disease',[
 ('Primary hemochromatosis as the usual malabsorptive cause','That causes iron loading rather than the usual iron-deficient phenotype.'),('An isolated high platelet count as a complete etiology','Reactive thrombocytosis can be an effect rather than the cause.'),('A normal serum sodium as exclusion of malabsorption','Sodium does not exclude celiac disease.')],
 'Malabsorption can present hematologically', '**Proximal small-bowel disease can impair iron uptake.**',['Celiac disease may have few GI symptoms.','Use an appropriate serological strategy with attention to IgA status and gluten exposure.'], '**Investigate persistent deficiency rather than repeatedly replacing iron alone.**',['Review adherence, ongoing loss and other absorption barriers.','Confirm a suspected cause through the appropriate pathway.'],[['Mechanism','Reduced iron absorption'],['Clue','Unexplained or refractory IDA'],['Assessment','Appropriate celiac testing']],[BS,GI])
q('Which oral-iron schedule reflects AGA 2024 best-practice advice for many adults with IDA?', 'Once daily at most, with every-other-day dosing an option for better tolerance',[
 ('Three large doses daily are mandatory for every adult','Frequent dosing can worsen adverse effects and is not the current universal advice.'),('One tablet monthly is adequate treatment for established deficiency','This does not provide a usual repletion course.'),('Every patient needs IV iron before an oral trial','Many patients can use oral therapy.')],
 'More frequent dosing is not automatically more effective', '**Once-daily or alternate-day schedules can improve practicality and tolerance.**',['Hepcidin responses influence absorption after oral dosing.','Select an appropriate elemental-iron amount and formulation.'], '**Check the response rather than assuming adherence and absorption.**',['GI adverse effects are common barriers.','Reassess hemoglobin and stores and review the cause of deficiency.'],[['Frequency','At most once daily'],['Alternative','Every other day for selected patients'],['Review','Tolerance and hematologic response']],[AG])
q('A patient after a malabsorptive bariatric procedure has persistent iron deficiency despite a properly taken oral trial and no untreated bleeding source. Which replacement route is appropriate?', 'Intravenous iron',[
 ('Continue escalating oral doses indefinitely despite demonstrated failure','Poor absorption can make this ineffective and poorly tolerated.'),('Therapeutic phlebotomy','This removes iron and worsens the problem.'),('Erythropoietin alone without correcting iron supply','This does not replace the deficient substrate.')],
 'The route should match the absorption problem', '**IV iron is appropriate when oral iron is not tolerated, ineffective or unlikely to be absorbed.**',['Bariatric anatomy can create a persistent absorption barrier.','Other nutrient deficiencies may coexist.'], '**Use a product-specific repletion and monitoring plan.**',['Review hypersensitivity and phosphate-related precautions.','Assess the later need for maintenance because the underlying absorption problem may persist.'],[['Oral failure','Check adherence, loss and absorption'],['Malabsorption','Supports IV route'],['Follow-up','Response and recurrent deficiency']],[AG],style='clinical_scenario')
q('Hemoglobin rises appropriately after oral iron, but stores remain depleted when Hb first normalizes. What is the usual principle?', 'Continue replacement for a period after Hb correction to replenish stores, with reassessment',[
 ('Stop immediately after the first normal Hb regardless of stores','The iron deficit may not yet be fully corrected.'),('Continue an unchanged dose lifelong in every patient without review','Duration depends on the cause, response and recurrence.'),('Begin iron chelation because Hb is normal','There is no evidence of iron excess in this description.')],
 'Hemoglobin recovery and store repletion do not occur simultaneously', '**BSG commonly advises continuing oral iron for about three months after Hb normalization.**',['The duration may vary with ongoing loss and absorption.','Monitor tolerance and the likelihood of recurrence.'], '**Reassess the etiological treatment as well.**',['Persistent bleeding can recreate the deficit.','Avoid both premature cessation and unreviewed indefinite supplementation.'],[['Early endpoint','Hb correction'],['Later endpoint','Store repletion'],['Duration','Often about 3 further months, individualized']],[BS],style='clinical_scenario')
q('After a well-conducted oral-iron trial, Hb fails to rise. Which next step is most appropriate?', 'Reassess adherence, dose, ongoing blood loss, absorption, inflammation and alternative or mixed diagnoses',[
 ('Conclude that iron deficiency never responds to therapy','Failure has several remediable explanations.'),('Assume every case is a hemoglobinopathy without checking stores','The initial and current evidence must be reviewed.'),('Double the dose repeatedly without evaluating the cause','This can worsen adverse effects without addressing the mechanism.')],
 'Nonresponse should trigger a structured review', '**Confirm that the diagnosis and delivered treatment are correct.**',['Ask directly about side effects and how tablets are taken.','Look for ongoing loss or an absorption barrier.'], '**Use the findings to change treatment rationally.**',['IV iron may be appropriate when oral delivery is ineffective.','A marrow, renal or other nutritional disorder may require separate treatment.'],[['Delivery','Adherence and tolerated elemental dose'],['Balance','Ongoing loss and absorption'],['Diagnosis','Inflammation or mixed disease']],[AG,BS],style='clinical_scenario')
